[CmdletBinding()]param([string]$ProjectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path,[string]$ReportPath='ES/Output/StaticReplay/es-abcd-stress.json',[int]$Rounds=8)
$ErrorActionPreference='Stop';$root=(Resolve-Path -LiteralPath $ProjectRoot).Path;Import-Module (Join-Path $root 'ES/Automation/ABCD/ESABCDFrameworkParity.psm1') -Force;$m=Get-ESABCDFrameworkCoverage;$cases=@();$sw=[Diagnostics.Stopwatch]::StartNew();foreach($round in 1..$Rounds){foreach($f in @($m.frameworks)){foreach($cap in @($f.capabilities)){$payload=[ordered]@{probe='stress';round=$round;framework=$f.frameworkId;scope='project';feedback='observed';reflection='bounded-reflection';count=2;max=3;used=0;output='';text='{}';maxLines=20;pruned=@('b1');backtrack=$true;seed='fixed';turns=3;stale=$false;score=0.7;expected='same';actual='same';trace=@('a','b');toolCalls=@('read')};try{$a=Invoke-ESABCDFrameworkCapability -FrameworkId $f.frameworkId -CapabilityId $cap -Payload $payload;$b=Invoke-ESABCDFrameworkCapability -FrameworkId $f.frameworkId -CapabilityId $cap -Payload $payload;$stable=([string]$a.inputHash -ceq [string]$b.inputHash -and [string]$a.status -ceq [string]$b.status);$cases+=,[pscustomobject]@{round=$round;framework=$f.frameworkId;capability=$cap;status=if($stable){'passed'}else{'failed'}}}catch{$cases+=,[pscustomobject]@{round=$round;framework=$f.frameworkId;capability=$cap;status='failed'}}}}};$sw.Stop();$failed=@($cases|Where-Object status -eq 'failed');$refs=@('ES/Automation/ABCD/ESABCDFrameworkParity.psm1','ES/Automation/ABCD/Test-ESABCDStress.ps1');$hashes=[ordered]@{};foreach($r in $refs){$hashes[$r]=(Get-FileHash -LiteralPath (Join-Path $root $r) -Algorithm SHA256).Hash.ToLowerInvariant()};$report=[ordered]@{schemaVersion=1;validator='Test-ESABCDStress';status=if($failed.Count){'failed'}else{'passed'};staticStatus=if($failed.Count){'static-failed'}else{'static-passed'};runtimeStatus='runtime-not-run';evidenceLevel='S1';capturedUtc=[DateTime]::UtcNow.ToString('o');rounds=$Rounds;caseCount=$cases.Count;passedCount=($cases.Count-$failed.Count);failedCount=$failed.Count;durationMs=$sw.ElapsedMilliseconds;cases=$cases;authorizationKind='read-only';evidenceContractId='es.skill-evidence-receipt';evidenceContractHash=(Get-FileHash -LiteralPath (Join-Path $root 'ES/Automation/Contracts/es-skill-evidence-receipt-v1.schema.json') -Algorithm SHA256).Hash.ToLowerInvariant();skillName='es-agent-mechanism-replication';case='abcd-stress';toolId='es-abcd-stress-validator';receiptPath=$ReportPath.Replace('\','/');sourceRefs=$refs;sourceRefHashes=$hashes;unityVersion='not-run';claimsNotProven=@('Unity/Worker runtime','production throughput')};$full=if([IO.Path]::IsPathRooted($ReportPath)){$ReportPath}else{Join-Path $root $ReportPath};New-Item -ItemType Directory -Force -Path (Split-Path -Parent $full)|Out-Null;[IO.File]::WriteAllText($full,($report|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$report|ConvertTo-Json -Depth 20;if($failed.Count){exit 1}
